"""The daemon's generated files: its HTTP routes, their JSON codec, and the API's OpenAPI document."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .generate import Model
from .http_routes import generate_routes
from .json_codec import generate_codec
from .openapi import convert, dumps, merge

# Included as the daemon includes them: core's C++ declarations from its SDK, the codec beside the routes.
API_HEADER = "api/Contract.h"
CODEC_HEADER = "api/generated/ContractJson.h"
# Where make -C contract update writes them, relative to the repository.
DAEMON_PATHS = {"ContractJson.h": "daemon/src/api/generated/ContractJson.h",
                "ContractRoutes.h": "daemon/src/api/generated/ContractRoutes.h"}
# RIG's document for the daemon's routes not yet in the contract, and the API's document, which adds the contract's.
RIG_OPENAPI = "api/rig/openapi.rig.json"
OPENAPI_PATHS = {"openapi.yaml": "api/openapi.yaml", "openapi.json": "api/openapi.json"}
YAML_HEADER = ("# Generated by RIG from the declarations in daemon/src/api, and by holder_contract from contract/;\n"
               "# edit those, then run make -C api/rig update and make -C contract update. Do not edit this file.\n")


def generate_daemon(ir: dict[str, Any]) -> dict[str, str]:
    """The generated files, by name, with the contract's OpenAPI paths on their own."""
    model = Model(ir)
    return {"ContractJson.h": generate_codec(model, API_HEADER),
            "ContractRoutes.h": generate_routes(model, CODEC_HEADER),
            "openapi.json": dumps(convert(model))}


def api_documents(ir: dict[str, Any], repository: Path) -> dict[str, str]:
    """The API's OpenAPI document, as YAML and JSON: RIG's routes and the contract's together."""
    rig = json.loads((repository / RIG_OPENAPI).read_text(encoding="utf-8"))
    document = merge(rig, convert(Model(ir)))
    return {"openapi.yaml": YAML_HEADER + dumps(document, "yaml"), "openapi.json": dumps(document)}
